Object.assign(D.B,{
mot_l2_intro:"<div class='mh'>تقديم الموضوع</div><p class='tx'>يُمثل الصدق لدى كل مسلم ومسلمة قيمة كبيرة، فهو قوام كل عمل وقمة الفضائل؛ فالله تعالى خلق السموات والأرض بالحق، وطلب من الناس أن يبنوا حياتهم على الحق؛ فلا يقولوا إلا حقًّا، ولا يعملوا إلا حقًّا.</p>",
mot_l2_story1:"<div class='mh'>عهد وميثاق</div><p class='tx'>أبو يزيد البسطامي هو: صوفي مسلم من أهل القرن الثالث الهجري، وُلد سنة ١٨٨هـ في بسطام في بلاد خراسان، وتوفي سنة ٢٦١هـ، عاش ٧٣ عامًا.</p><p class='tx'>يحكى أن أبا يزيد البسطامي الصوفي أراد الذهاب إلى بغداد لطلب العلم، فأعطته أمه أربعين دينارًا هي ميراثه من أبيه، وقالت له: ضع يدك في يدي، وعاهدني على التزام الصدق فلا تكذب أبدًا، فعاهدها على ذلك، وخرج مع قافلة يريد بغداد.</p>",
mot_l2_story2:"<div class='mh'>توبة اللصوص مع كبيرهم</div><p class='tx'>في أثناء الطريق خرج اللصوص ونهبوا كل ما في القافلة، ورأوا البسطامي رث الثياب، فقالوا له: هل معك شيء؟ فقال: معي أربعون دينارًا، فسخروا منه وحسبوا أنه أبله وتركوه، ورجعوا إلى كهف كان به كبير اللصوص.</p><p class='tx'>فلما أخبروا كبيرهم أمرهم أن يأتوا به، وقال له: هل معك شيء؟ فقال: نعم، معي أربعون دينارًا، فأخرجها وسلمها له، فقال كبير اللصوص: أمجنون أنت يا رجل؟ كيف ترشد عن نقودك وتسلمها باختيارك؟ فقال البسطامي: لما أردت الخروج من بلدي عاهدت أمي على الصدق، فأنا لا أنقض عهد أمي. فقال كبير اللصوص: أنت تخاف أن تخون عهد أمك، ونحن لا نخاف أن نخون عهد الله!</p><p class='tx'>آثر هذا الحوار في كبير اللصوص ومن معه؛ فأمر برد جميع ما أُخذ من القافلة، وقال: أنا تائب على يديك يا رجل، فقال من معه: أنت كبيرنا في قطع الطريق، واليوم أنت كبيرنا في التوبة، تبنا جميعًا إلى الله، وتابوا وحسنت توبتهم.</p>",
mot_l2_fadila:"<div class='mh'>فضيلة الصدق</div><p class='tx'>لَم تحظ فضيلة من الفضائل بما حظيت به فضيلة الصدق من التحبيب فيها، والحث على التزامها؛ قال تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ﴾.</p><p class='tx'>وقد امتدح الله تعالى بعض أنبيائه بها؛ قال تعالى: ﴿وَاذْكُرْ فِي الْكِتَابِ إِسْمَاعِيلَ إِنَّهُ كَانَ صَادِقَ الْوَعْدِ﴾ [مريم: 54]، وقال جل شأنه: ﴿وَاذْكُرْ فِي الْكِتَابِ إِدْرِيسَ إِنَّهُ كَانَ صِدِّيقًا نَبِيًّا وَرَفَعْنَاهُ مَكَانًا عَلِيًّا﴾ [مريم: 56-57].</p><p class='tx'>ومن السنة قول الرسول ﷺ: «إن الصدق يهدي إلى البر، وإن البر يهدي إلى الجنة، وإن الرجل ليصدق حتى يُكتب عند الله صديقًا، وإن الكذب يهدي إلى الفجور، وإن الفجور يهدي إلى النار، وإن الرجل ليكذب حتى يُكتب عند الله كذابًا» (متفق عليه).</p>",
mot_l2_aqiba:"<div class='mh'>عاقبة الصدق وعاقبة الكذب</div><p class='tx'>قال بعض الحكماء: «الصدق ينجيك وإن خفته، والكذب يرديك وإن أمنته».</p><p class='tx'>وقيل: «صدق اللسان أول السعادة، والكذب جماع كل شر وأصل كل ذم؛ لسوء عاقبته وخبيث نتائجه».</p>"
});
Object.assign(D.B,{
mot_l2_vocab1:"<div class='mh'>المفردات اللغوية (1)</div><table class='tbl'><tr><th>الكلمة</th><th>معناها</th></tr><tr><td>قيمة</td><td>أهمية، والجمع: قِيَم</td></tr><tr><td>الفضائل</td><td>الأخلاق الطيبة، ومفردها: فضيلة، والمضاد: الرذائل</td></tr><tr><td>بغداد</td><td>عاصمة العراق</td></tr><tr><td>ميراثه</td><td>تركته، وجمعها: مواريث</td></tr><tr><td>التصوف</td><td>طريقة من السلوك تعتمد على التحلي بالفضائل وتزكية النفس</td></tr><tr><td>القافلة</td><td>الرفقة الكبيرة الراجعة من السفر أو المبتدئة به، والجمع: قوافل</td></tr><tr><td>الدينار</td><td>نقد ذهب، وهو اليوم عملة في بعض الدول العربية، والجمع: الدنانير</td></tr><tr><td>القرن</td><td>مائة سنة، والجمع: قرون</td></tr><tr><td>الصوفي</td><td>من يتبع طريقة التصوف، والجمع: الصوفية</td></tr></table>",
mot_l2_vocab2:"<div class='mh'>المفردات اللغوية (2)</div><table class='tbl'><tr><th>الكلمة</th><th>معناها</th></tr><tr><td>نقودك</td><td>مفردها: نقد، وهي العملة من الذهب أو الفضة وغيرهما مما يتعامل به</td></tr><tr><td>أبله</td><td>ضعف عقله وغلبت عليه الغفلة، ومؤنثه: بلهاء، والجمع: بله</td></tr><tr><td>نهبوا</td><td>سلبوا، والمضاد: أعطوا ومنحوا</td></tr><tr><td>رث الثياب</td><td>رديء الملبس (يرتدي ثوبًا باليًا قديمًا)، ومضاد رث: جديد</td></tr><tr><td>لا أنقض</td><td>لا أخالف</td></tr><tr><td>كهف</td><td>بيت منقور في الجبل أو الصخر، وجمعها: كهوف</td></tr><tr><td>خبل</td><td>فساد العقل (به مس من الجنون)، ومضاده: عقل</td></tr><tr><td>ترشد</td><td>تهدي وتدل، ومضادها: تضل</td></tr></table>",
mot_l2_vocab3:"<div class='mh'>المفردات اللغوية (3)</div><table class='tbl'><tr><th>الكلمة</th><th>معناها</th></tr><tr><td>تحظى</td><td>تنعم وتنال</td></tr><tr><td>الحث</td><td>التشجيع والتحبيب، ومضادها: التنفير والتحذير</td></tr><tr><td>يرديك</td><td>يهلكك، ومضادها: ينجيك</td></tr><tr><td>جماع كل شر</td><td>ما يجمع أصول الشر وعناصره</td></tr><tr><td>عواقبه</td><td>نتائجه وآثاره، ومفردها: عاقبة</td></tr><tr><td>يهدي</td><td>يرشد ويدل، ومضادها: يضل</td></tr></table>",
mot_l2_values:"<div class='mh'>القيم المكتسبة من الدرس (الدروس المستفادة)</div><ul class='dash'><li>من البر بالوالدين: الاستجابة لنصحهما.</li><li>لا يوصف المؤمن بالكذب.</li><li>يقبل الله التوبة الصادقة مهما كان الذنب.</li><li>الكذب يضر بالمرء ولو ظن أن فيه النجاة.</li></ul>",
mot_l2_rel:"<div class='mh'>العلاقات بين الجمل والكلمات في الموضوع</div><p class='tx'>العلاقات بين الجمل:</p><ul class='dash'><li>(لطلب العلم): علاقتها بما قبلها التعليل.</li><li>(هي ميراثه من أبيه): علاقتها بما قبلها التوضيح.</li><li>(عاهدت أمي على الصدق): علاقتها بما قبلها التعليل.</li><li>(فسخروا منه): علاقتها بما قبلها النتيجة.</li><li>(إن الصدق يهدي إلى البر - إن الكذب يهدي إلى الفجور): علاقتها المقابلة.</li></ul><p class='tx'>العلاقات بين الكلمات:</p><ul class='dash'><li>(يهدي - يرشد - يدل): ترادف.</li><li>(ثوب - أثواب - ثياب): اشتراك في الأصل.</li><li>(الصدق - الكذب): تضاد.</li><li>(الأم - الأب): تكاملية.</li></ul>"
});
if(S)Object.assign(S,{
mot_l2_intro:"الصدق عند كل مسلم ومسلمة قيمة كبيرة، هو أساس كل عمل وأعلى الفضائل. ربنا خلق السماوات والأرض بالحق، وطلب مننا نبني حياتنا على الحق: لا نقول إلا حق ولا نعمل إلا حق.",
mot_l2_story1:"أبو يزيد البسطامي صوفي مسلم من أهل القرن التالت الهجري، اتولد سنة ١٨٨هـ في بسطام في بلاد خراسان، وتوفي سنة ٢٦١هـ عن ٧٣ سنة. أراد يسافر بغداد يطلب العلم، فأمه ادته أربعين دينار (هي ميراثه من أبوه)، وقالت له: حط إيدك في إيدي وعاهدني إنك ملتزم الصدق وماتكذبش أبدًا، فعاهدها وسافر مع قافلة رايحة بغداد.",
mot_l2_story2:"في نص الطريق اللصوص هجموا ونهبوا كل حاجة في القافلة. شافوا البسطامي لابس هدوم رثة، سألوه: معاك حاجة؟ قال بصدق: معايا أربعين دينار. سخروا منه وحسبوه أبله وسابوه. لما رجعوا للكهف وقالوا لكبيرهم، طلب يجيبوه، فقال نفس الكلام وسلم الفلوس باختياره. كبير اللصوص اتعجب: إنت مجنون؟ فقال البسطامي: أنا عاهدت أمي على الصدق ومش هنقض عهدها. فكبير اللصوص قال: إنت خايف تخون عهد أمك، وإحنا مش خايفين نخون عهد ربنا! الكلام ده أثر فيه وفي اللي معاه، فرجع المنهوبات كلها للقافلة وقال: أنا تائب على إيدك، واللصوص قالوا: إنت كبيرنا في قطع الطريق والنهارده كبيرنا في التوبة، وتابوا كلهم وحسنت توبتهم.",
mot_l2_fadila:"مفيش فضيلة نالت من التحبيب والحث عليها زي فضيلة الصدق. ربنا أمرنا نكون مع الصادقين، ومدح أنبياءه بالصدق زي إسماعيل (كان صادق الوعد) وإدريس (كان صديقًا نبيًّا). والحديث بيبين إن الصدق طريقه للبر والبر للجنة، والكذب طريقه للفجور والفجور للنار، واللي يداوم على الصدق يتكتب عند ربنا صديق، واللي يداوم على الكذب يتكتب كذاب.",
mot_l2_aqiba:"الحكماء قالوا: الصدق بينجيك حتى لو خفت منه، والكذب بيهلكك حتى لو حسيت إنك في أمان. وقيل: صدق اللسان أول السعادة، والكذب بيجمع كل شر وهو أصل كل عيب؛ لأن عواقبه وحشة ونتائجه خبيثة.",
mot_l2_vocab1:"قيمة يعني أهمية وجمعها قِيَم. الفضائل هي الأخلاق الطيبة ومفردها فضيلة ومضادها الرذائل. بغداد عاصمة العراق. ميراثه يعني تركته وجمعها مواريث. التصوف طريقة سلوك بتعتمد على التحلي بالفضائل وتزكية النفس، والصوفي هو اللي بيتبعها. القافلة رفقة كبيرة في السفر وجمعها قوافل. الدينار نقد ذهب وجمعه دنانير. القرن مية سنة.",
mot_l2_vocab2:"نقود مفردها نقد وهي العملة اللي الناس بتتعامل بيها. أبله يعني ضعف عقله وغلبت عليه الغفلة. نهبوا يعني سلبوا ومضادها أعطوا ومنحوا. رث الثياب يعني رديء الملبس ومضاد رث جديد. لا أنقض يعني لا أخالف. كهف بيت منقور في الجبل أو الصخر وجمعها كهوف. خبل فساد العقل ومضاده عقل. ترشد يعني تهدي وتدل ومضادها تضل.",
mot_l2_vocab3:"تحظى يعني تنعم وتنال. الحث يعني التشجيع والتحبيب ومضاده التنفير والتحذير. يرديك يعني يهلكك ومضادها ينجيك. جماع كل شر يعني اللي بيجمع أصول الشر وعناصره. عواقبه يعني نتائجه ومفردها عاقبة. يهدي يعني يرشد ويدل ومضادها يضل.",
mot_l2_values:"الدروس المستفادة من القصة: من بر الوالدين إنك تسمع نصيحتهم زي ما البسطامي عمل. المؤمن ميتوصفش بالكذب أبدًا. ربنا بيقبل التوبة الصادقة مهما كان الذنب كبير زي توبة اللصوص. والكذب بيضر صاحبه حتى لو فاكر إن فيه نجاة.",
mot_l2_rel:"مراجعة العلاقات: (لطلب العلم) جملة تعليل لإنها بتبين سبب الذهاب. (هي ميراثه من أبيه) جملة توضيح لإنها بتفسر مصدر الدنانير. (فسخروا منه) جملة نتيجة لإنها نتيجة حسبانهم إنه أبله. و(إن الصدق يهدي إلى البر / إن الكذب يهدي إلى الفجور) علاقتهم مقابلة. وفي الكلمات: يهدي ويرشد ويدل ترادف، ثوب وأثواب وثياب اشتراك في الأصل، الصدق والكذب تضاد، الأم والأب تكاملية."
});
