mot_l3_vocab4:"<div class='mh'>المفردات اللغوية (4)</div><table class='tbl'><tr><th>الكلمة</th><th>معناها</th></tr><tr><td>يسمو</td><td>يرتفع</td></tr><tr><td>جوف الليل</td><td>الثلث الأخير من الليل</td></tr><tr><td>جمة</td><td>مجتمعة وكثيرة</td></tr><tr><td>يتفقد</td><td>يتعرف أحوالهم ليطمئن عليهم</td></tr><tr><td>امذقيه</td><td>اخلطيه</td></tr><tr><td>لا يشاب</td><td>لا يخلط</td></tr><tr><td>الزاهد</td><td>العابد، وهو المنصرف عن الدنيا إلى الآخرة، والجمع: الزهاد والزهد</td></tr><tr><td>التجوال</td><td>السير</td></tr><tr><td>الصبية</td><td>الفتاة، وجمعها: الصبايا</td></tr><tr><td>موضع</td><td>مكان، وجمعها: مواضع</td></tr></table>",
